```c
static int sf32lb52_wrrequest(struct sf32lb52_ep_s *privep)
{
  struct sf32lb52_req_s *privreq;
  uint8_t *buf;
  int nbytes;
  int bytesleft;
  int nbyteswritten;

  privreq = sf32lb52_rqpeek(privep);
  if (!privreq)
    {
      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_NULLREQUEST), 0);
      return OK;
    }

  bytesleft = privreq->req.len - privreq->req.xfrd;

  usbtrace(TRACE_WRITE(privep->epphy), privreq->req.xfrd);

  /* Transmit at most one packet per call.  The MUSB controller requires
   * the host to drain the FIFO (TXPKTRDY auto-clears -> TX-complete
   * interrupt) before the next packet is written; chaining packets here
   * overwrites the FIFO and corrupts multi-packet transfers such as the
   * 75-byte configuration descriptor on EP0.
   */

  if (bytesleft > 0 || privep->txnullpkt)
    {
      privep->txnullpkt = 0;
      if (bytesleft > privep->ep.maxpacket)
        {
          nbytes = privep->ep.maxpacket;
        }
      else
        {
          nbytes = bytesleft;
          if ((privreq->req.flags & USBDEV_REQFLAGS_NULLPKT) != 0)
            {
              privep->txnullpkt = (bytesleft == privep->ep.maxpacket);
            }
        }

      buf = privreq->req.buf + privreq->req.xfrd;
      nbyteswritten = sf32lb52_epwrite(privep->dev, privep->epphy,
                                       buf, nbytes);
      if (nbyteswritten < 0 || nbyteswritten != nbytes)
        {
          usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_EWRITE),
                   nbyteswritten);
          return ERROR;
        }

      privreq->req.xfrd += nbytes;
    }

  /* If the whole request fits in this one packet (and no null packet is
   * pending), the transfer is complete now.  Otherwise the TX-complete
   * interrupt will call us again to send the next packet.
   */

  if (privreq->req.xfrd >= privreq->req.len && !privep->txnullpkt)
    {
      usbtrace(TRACE_COMPLETE(privep->epphy), privreq->req.xfrd);
      privep->txnullpkt = 0;
      sf32lb52_reqcomplete(privep, OK);
    }

  return OK;
}
